import { Injectable } from '@angular/core';
import { Observable, of } from 'rxjs';
import { Country } from './types';
import { HttpClient } from '@angular/common/http';

const COUNTRIES: Country[] = [
  { id: 'empty', description: '', currency: '' },
  { id: 'US', description: 'United States', currency: 'USD' },
  { id: 'CA', description: 'Canada', currency: 'CAD' },
  { id: 'UK', description: 'United Kingdom', currency: 'GBP' },
  { id: 'AU', description: 'Australia', currency: 'AUD' },
  { id: 'NZ', description: 'New Zealand', currency: 'NZD' },
];

@Injectable({
  providedIn: 'root'
})
export class CountryService {

constructor(private http: HttpClient){}

  getCountries(): Observable<Country[]> {
    // return of(COUNTRIES);
    return this.http.get<Country[]>('http:localhost:3000/countries');
  }
}
